+static Selectivity
+mcv_population(float4 *mcv_numbers, int mcv_nvalues)
+{
+   Selectivity sumcommon = 0.0;
+   int         i;
+
+   for (i = 0; i < mcv_nvalues; i++)
+   {
+       sumcommon += mcv_numbers[i];
+   }
+
+   return sumcommon;
+}
