+int
+read_objtype_from_string(const char *objtype)
+{
+   ObjectType  type;
+   int         i;
+
+   for (i = 0; i < lengthof(ObjectTypeMap); i++)
+   {
+       if (strcmp(ObjectTypeMap[i].tm_name, objtype) == 0)
+       {
+           type = ObjectTypeMap[i].tm_type;
+           break;
