+   }
+   if (i >= lengthof(ObjectTypeMap))
+       ereport(ERROR,
+              (errcode(ERRCODE_INVALID_PARAMETER_VALUE),
+               errmsg("unrecognized object type \"%s\"", objtype)));
+
+   return type;
+}
